/**
 * Public surface of `@adistack/data-explorer`.
 *
 * Explicit allow-list (no `export *`): every name here is the stable
 * contract — renames elsewhere don't break consumers, and bundlers can
 * tree-shake cleanly. Canonical home per domain:
 * columns → `./columns.ts`, filters → `./filters.ts`, display snapshots
 * + share-link codec → `./features/display-snapshot.ts`, filter
 * serialization → `./features/data-filtering/filter-utils.ts`, query keys
 * → `./query.ts`. (`types.ts` owns the context shape only; it is not a
 * barrel.)
 */

// --- Columns (`./columns.ts`) ---
export {
	type ColumnConfig,
	type ColumnDataType,
	type ColumnIssue,
	type ColumnSemantics,
	type DataExplorerColumnMeta,
	type ExtractColumnConfigOptions,
	extractColumnConfigs,
	extractColumnConfigsDetailed,
	isSearchColumn,
	isSearchColumnId,
	SEARCH_COLUMN_ID,
} from "./columns.ts";
// --- Context + provider shell. ---
export {
	DataExplorerContext,
	useDataExplorerContext,
} from "./context.tsx";
// --- Errors (`./errors.ts`): match on `error.code`, never on messages. ---
export {
	DataExplorerError,
	type DataExplorerErrorCode,
	MissingProviderError,
} from "./errors.ts";
// --- Table features. ---
export { dataFilteringFeature } from "./features/data-filtering/dataFilteringFeature.ts";
// --- Filter authoring: schemas, drafts, semantics. ---
export {
	filterConditionSchema,
	makeFilterConditionSchema,
} from "./features/data-filtering/filter-condition-schema.ts";
export {
	buildDraftCondition,
	commitDraft,
	createSearchFilter,
	type DraftCommit,
	editorKind,
	type FilterEditorKind,
	type FormatFilterValueOptions,
	formatFilterValue,
	quickAddCondition,
} from "./features/data-filtering/filter-draft.ts";
export {
	type ColumnSelectDecision,
	type FlowAction,
	type FlowState,
	flowReducer,
	INITIAL_FLOW,
	type Phase,
	resolveColumnSelect,
	resolveOperatorSelect,
} from "./features/data-filtering/filter-flow-reducer.ts";
export { groupConditions } from "./features/data-filtering/filter-grouping.ts";
export {
	type CoercedFilterValue,
	type ConditionValidationError,
	coerceFilterValue,
	validateCondition,
	validateFilterValue,
} from "./features/data-filtering/filter-semantics.ts";
export {
	deserializeFilters,
	FILTER_SERIALIZATION_VERSION,
	serializeFilters,
} from "./features/data-filtering/filter-utils.ts";
export {
	FILTER_OPERATORS,
	getDefaultOperator,
	getOperatorArity,
	getOperatorLabel,
	getOperatorsForType,
	normalizeOperator,
	type OperatorArity,
} from "./features/data-filtering/operators.ts";
export {
	type InlineFilterActions,
	type InlineFilterState,
	useInlineFilterFlow,
} from "./features/data-filtering/use-inline-filter-flow.ts";
export { displayMetaFeature } from "./features/display-meta/displayMetaFeature.ts";
// --- Display snapshots (canonical home for `mergeDisplay` + share-link codec). ---
export {
	applyDisplaySnapshot,
	applyTableSnapshot,
	DENSITIES,
	deserializeDisplay,
	mergeDisplay,
	serializeDisplay,
	toDisplaySnapshot,
	toInitialColumnVisibility,
	toInitialGrouping,
	toInitialSorting,
	toInitialTableState,
	VIEW_TYPES,
} from "./features/display-snapshot.ts";
// --- Filters (`./filters.ts`) ---
export {
	createFilter,
	type FilterCondition,
	type FilterGroup,
	type FilterOperator,
	hasFilters,
	isFilterGroup,
	type SerializedFilterCondition,
	type TypedFilterValue,
} from "./filters.ts";
// --- Hooks. ---
export {
	DEFAULT_PAGE_SIZE,
	useDataQuery,
} from "./hooks/use-data-query.ts";
export { useLoadMore } from "./hooks/use-load-more.ts";
export {
	type SelectionState,
	useSelectionContext,
} from "./hooks/use-selection.ts";
export { useView, viewQueryKey } from "./hooks/use-view.ts";
/** Headless provider — see `DataExplorerProviderProps` for the contract. */
export {
	type DataExplorerProviderProps,
	Provider,
	Provider as DataExplorerProvider,
} from "./provider.tsx";
// --- Query (`./query.ts`: canonical home for keys + hashing). ---
export type {
	DataQueryKeyRefine,
	DataRefineOptions,
	ListQueryResult,
	RefineOptions,
	SortDirection,
	SortOrder,
} from "./query.ts";
export {
	dataQueryKey,
	hashRefine,
	stableStringify,
} from "./query.ts";
// --- SQL helper. ---
export {
	type BuildFilterOptions,
	buildFilterWhere,
	type ColumnMapping,
	type ParameterizedSql,
	type PlaceholderStyle,
	type SqlDialect,
} from "./sql/index.ts";
// --- Context shape (`./types.ts`: owns `BoardMove*` + context only). ---
export type {
	BoardMoveArgs,
	BoardMoveHandler,
	DataExplorerContextValue,
	DataExplorerViewState,
	TableFeatures,
} from "./types.ts";
// --- Views (`./views.ts`) ---
export type {
	Density,
	FilterViewDisplay,
	View,
	ViewAdapter,
	ViewType,
} from "./views.ts";

import { createContext, useContext } from "react";

import { MissingProviderError } from "./errors.ts";
import type { DataExplorerContextValue } from "./types.ts";

export const DataExplorerContext = createContext<DataExplorerContextValue<
	Record<string, unknown>
> | null>(null);

/**
 * Read the explorer context (table instance, column configs, data, view state).
 * Must run inside `<Provider>` — otherwise throws {@link MissingProviderError}.
 *
 * @example
 * ```tsx
 * const { table } = useDataExplorerContext<Task>();
 * const filters = table.state.dataFilters;
 * ```
 */
export function useDataExplorerContext<
	TItem extends Record<string, unknown> = Record<string, unknown>,
>(): DataExplorerContextValue<TItem> {
	const value = useContext(DataExplorerContext);
	if (!value) {
		throw new MissingProviderError("useDataExplorerContext");
	}
	return value as unknown as DataExplorerContextValue<TItem>;
}

import type { UseQueryOptions } from "@tanstack/react-query";
import { QueryClientContext } from "@tanstack/react-query";
import type { ColumnDef } from "@tanstack/react-table";
import { useTable } from "@tanstack/react-table";
import {
	useCallback,
	useContext,
	useEffect,
	useMemo,
	useRef,
	useState,
} from "react";

import type { ExtractColumnConfigOptions } from "./columns.ts";
import { extractColumnConfigs } from "./columns.ts";
import { DataExplorerContext } from "./context.tsx";
import { DataExplorerError } from "./errors.ts";
import { toInitialTableState } from "./features/display-snapshot.ts";
import { TableFeatures } from "./features/index.ts";
import { useDataQuery } from "./hooks/use-data-query.ts";
import { useLoadMore } from "./hooks/use-load-more.ts";
import { useView } from "./hooks/use-view.ts";
import type { DataRefineOptions, ListQueryResult } from "./query.ts";
import type { BoardMoveHandler, DataExplorerContextValue } from "./types.ts";
import type { FilterViewDisplay, ViewAdapter } from "./views.ts";

/** Props for {@link Provider}. */
export interface DataExplorerProviderProps<
	TItem extends Record<string, unknown>,
> {
	children: React.ReactNode;
	/** Memoize in the consumer to avoid recomputing `columnsConfig` per render. */
	columns: ColumnDef<typeof TableFeatures, TItem>[];
	/** Debounce for filter keystrokes before they enter the query key. @default 0 (off) */
	debounceFiltersMs?: number;
	/**
	 * Applied once as table `initialState` (uncontrolled). Changes after
	 * mount are ignored — apply updates via `applyDisplaySnapshot`/table
	 * APIs, or key the provider (`<Provider key={domain}>`) for a hard reset.
	 */
	defaultDisplay: FilterViewDisplay;
	domain: string;
	getRowId: (row: TItem) => string;
	/** Called once per skipped column definition (library never logs). */
	onInvalidColumn?: ExtractColumnConfigOptions["onInvalidColumn"];
	/** Board card moves. Held in a ref — inlining the handler won't re-render consumers. */
	onMove?: BoardMoveHandler;
	/** Rows per page. @default DEFAULT_PAGE_SIZE (20) */
	pageSize?: number;
	query: (opts: DataRefineOptions) => UseQueryOptions<ListQueryResult<TItem>>;
	/** Forwarded to TanStack as `staleTime`. */
	staleTime?: number;
	/** Fail fast on invalid column definitions. */
	strictColumns?: boolean;
	viewAdapter?: ViewAdapter;
}

/** Throw an actionable error when no `QueryClientProvider` ancestor exists. */
function useQueryClientGuard(): void {
	const client = useContext(QueryClientContext);
	if (!client) {
		throw new DataExplorerError(
			"MISSING_QUERY_CLIENT",
			"Wrap <Provider> in <QueryClientProvider>.",
		);
	}
}

/**
 * Headless data-explorer provider: owns the single TanStack table instance,
 * the infinite data query, and persisted-view state.
 *
 * Data flows `table.state → query → allItems → tableData → table.data`.
 * The `tableData` state + effect hop breaks the hook-order cycle (`useTable`
 * needs data that `useDataQuery` computes from `table.state`), with no
 * render-phase `setState` and no `table.options` mutation. Context consumers
 * read the same `tableData` reference the table sees. Requires a
 * `QueryClientProvider` ancestor.
 *
 * @example
 * ```tsx
 * <QueryClientProvider client={client}>
 *   <Provider columns={cols} defaultDisplay={DEFAULT_DISPLAY} domain="tasks"
 *     getRowId={(r) => r.id} query={createMemoryQuery(TASKS)}>
 *     <FilterBar />
 *   </Provider>
 * </QueryClientProvider>
 * ```
 */
export function Provider<TItem extends Record<string, unknown>>({
	children,
	columns,
	defaultDisplay,
	domain,
	getRowId,
	onMove,
	query: queryBuilder,
	viewAdapter,
	pageSize,
	staleTime,
	debounceFiltersMs,
	onInvalidColumn,
	strictColumns,
}: DataExplorerProviderProps<TItem>) {
	useQueryClientGuard();

	// Latest `onMove` rides a ref so the context value stays stable when a
	// consumer inlines the handler. Presence (`undefined` vs defined) is
	// still derived from the prop, so board drop-targets keep working.
	const onMoveRef = useRef(onMove);
	useEffect(() => {
		onMoveRef.current = onMove;
	}, [onMove]);
	const handleMove = useCallback(
		(...args: Parameters<NonNullable<typeof onMove>>) =>
			onMoveRef.current?.(...args),
		[],
	);
	const stableOnMove = onMove ? handleMove : undefined;

	const columnsConfig = useMemo(
		() =>
			extractColumnConfigs(columns, {
				onInvalidColumn,
				strict: strictColumns,
			}),
		[columns, onInvalidColumn, strictColumns],
	);

	// Uncontrolled by design: frozen on first render via lazy `useState`.
	const [frozenInitialState] = useState(() => ({
		...toInitialTableState(defaultDisplay, columnsConfig),
		dataFilters: [],
	}));

	// The `table.state → query → data → table` hook-order cycle is broken
	// by this state + effect hop: the table reads `tableData`, the query
	// reads `table.state`, and fresh pages land here one commit later.
	// `allItems` is stable (empty singleton until pages arrive), so this
	// only re-renders when fresh pages land. `context.items` reads the
	// same `tableData` reference below, so consumers never observe rows
	// the table instance doesn't know about yet.
	const [tableData, setTableData] = useState<TItem[]>([]);

	const table = useTable({
		autoResetAll: false,
		columns,
		data: tableData,
		enableGrouping: true,
		enableHiding: true,
		enableSorting: true,
		enableSortingRemoval: true,
		features: TableFeatures,
		getRowId,
		initialState: frozenInitialState,
		manualGrouping: true,
		manualSorting: true,
	});

	const sorting = table.state.sorting;
	const grouping = table.state.grouping;
	const dataFilters = table.state.dataFilters ?? [];

	const { allItems, query } = useDataQuery<TItem>({
		dataFilters,
		debounceFiltersMs,
		domain,
		grouping,
		pageSize,
		queryBuilder,
		sorting,
		staleTime,
	});

	useEffect(() => {
		setTableData(allItems);
	}, [allItems]);

	const viewHook = useView<TItem>({
		columnsConfig,
		defaultDisplay,
		domain,
		table,
		viewAdapter,
	});

	const { triggerRef } = useLoadMore(
		query.fetchNextPage,
		query.hasNextPage,
		query.isFetchingNextPage,
	);

	// Destructure so memo deps are primitives + stable callbacks — not the
	// `viewHook` object identity (which would re-render every consumer).
	const {
		activeView,
		activeViewId,
		applyView,
		createView,
		deleteView,
		error: viewError,
		isLoading: viewsLoading,
		renameView,
		resetToSaved,
		saveView,
		views,
	} = viewHook;

	const hasNextPage = query.hasNextPage;
	const isLoading = query.isLoading;
	const isFetchingNextPage = query.isFetchingNextPage;

	const contextValue: DataExplorerContextValue<TItem> = useMemo(
		() => ({
			columnsConfig,
			data: {
				hasMore: hasNextPage,
				isLoading,
				isLoadingMore: isFetchingNextPage,
				items: tableData,
				loadMoreRef: triggerRef,
			},
			onMove: stableOnMove,
			table,
			view: {
				activeView,
				activeViewId,
				applyView,
				createView,
				deleteView,
				error: viewError,
				isLoading: viewsLoading,
				renameView,
				resetToSaved,
				saveView,
				views,
			},
		}),
		[
			columnsConfig,
			hasNextPage,
			isLoading,
			isFetchingNextPage,
			tableData,
			triggerRef,
			stableOnMove,
			table,
			activeView,
			activeViewId,
			applyView,
			createView,
			deleteView,
			viewError,
			viewsLoading,
			renameView,
			resetToSaved,
			saveView,
			views,
		],
	);

	return (
		<DataExplorerContext
			value={
				// The context is intentionally non-generic (one shared
				// instance); the cast restores the row type at consumption.
				contextValue as unknown as DataExplorerContextValue<
					Record<string, unknown>
				>
			}
		>
			{children}
		</DataExplorerContext>
	);
}

import type { ReactTable } from "@tanstack/react-table";

import type { ColumnConfig } from "./columns.ts";
import type { TableFeatures as $TableFeatures } from "./features/index.ts";
import type { View } from "./views.ts";

export type TableFeatures = typeof $TableFeatures;

/** Board drag-and-drop move descriptor. */
export interface BoardMoveArgs {
	columnId: string;
	fromGroup: string;
	itemId: string;
	toGroup: string;
}

/** Handler for board card moves (`Provider` `onMove` prop). */
export type BoardMoveHandler = (args: BoardMoveArgs) => void;

/** View slice of the explorer context (persisted views). */
export interface DataExplorerViewState {
	activeView?: View | null;
	activeViewId: string | null;
	applyView: (viewId: string | null) => void;
	createView: (
		name: string,
		data?: { display?: View["display"]; refine?: View["refine"] },
	) => Promise<View>;
	deleteView: (viewId: string) => Promise<boolean>;
	error: unknown;
	isLoading: boolean;
	renameView: (viewId: string, name: string) => Promise<View>;
	/** Resets to `defaultDisplay` + empty filters when nothing is saved. */
	resetToSaved: () => void;
	/** Persists the active view. Returns `false` when no view is active; throws `VIEWS_NOT_CONFIGURED` without an adapter. */
	saveView: () => Promise<boolean>;
	views?: View[];
}

/**
 * Canonical context value. Parameterized by row type so `table`,
 * `row.original`, and `data.items` stay typed end to end.
 */
export interface DataExplorerContextValue<
	TItem extends Record<string, unknown> = Record<string, unknown>,
> {
	columnsConfig: ColumnConfig[];
	data: {
		hasMore: boolean;
		isLoading: boolean;
		isLoadingMore: boolean;
		items: TItem[];
		loadMoreRef: (el: Element | null) => void;
	};
	onMove?: BoardMoveHandler;
	table: ReactTable<TableFeatures, TItem>;
	view: DataExplorerViewState;
}

import type { DataExplorerErrorCode } from "./errors.ts";
import { DataExplorerError } from "./errors.ts";
import type { FilterOperator } from "./filters.ts";

export type ColumnDataType =
	| "string"
	| "number"
	| "date"
	| "boolean"
	| "enum"
	| "multiEnum";

/**
 * Global-search pseudo column.
 *
 * Divergence contract: drafts targeting `_search` pin the `contains`
 * operator and jump straight to the value phase (`filter-draft.ts`), and
 * the SQL builder fans the term out to `ILIKE … OR …` across every
 * `searchable` column (`sql/filter-sql.ts`). Never hand-build
 * `{ columnId: "_search", operator: "contains" }` — use
 * {@link createSearchFilter} instead.
 */
export const SEARCH_COLUMN_ID = "_search" as const;

export function isSearchColumnId(id: string): boolean {
	return id === SEARCH_COLUMN_ID;
}

export function isSearchColumn(col: { id: string } | string): boolean {
	return typeof col === "string"
		? isSearchColumnId(col)
		: isSearchColumnId(col.id);
}

export interface DataExplorerColumnMeta<TIcon = unknown> {
	displayName: string;
	endOf?: "timeline";
	icon?: TIcon;
	max?: number;
	min?: number;
	operators?: FilterOperator[];
	options?: { label: string; value: string }[];
	/** Override for single-click quick-add (`quickAddCondition`). Defaults to `includeAny` on `multiEnum`, `eq` elsewhere. */
	quickOperator?: FilterOperator;
	searchable?: boolean;
	startOf?: "timeline";
	type: ColumnDataType;
}

/** Minimal column shape for filter semantics (operator allow-list + type). */
export type ColumnSemantics = Pick<
	DataExplorerColumnMeta,
	"operators" | "type"
>;

/** Headless column descriptor derived from a TanStack column def's `meta`. */
export interface ColumnConfig<TIcon = unknown>
	extends DataExplorerColumnMeta<TIcon> {
	id: string;
}

/** One skipped column definition, collected instead of `console.warn`. */
export interface ColumnIssue {
	code: DataExplorerErrorCode;
	/** The offending `id`, when the definition had one. */
	id?: string;
	index: number;
	message: string;
}

export interface ExtractColumnConfigOptions {
	/**
	 * Called once per skipped definition. When omitted, issues are silently
	 * skipped (library code never logs). Pass `strict: true` to throw instead.
	 */
	onInvalidColumn?: (issue: ColumnIssue) => void;
	/** Fail fast with `DataExplorerError("INVALID_COLUMN_DEF")` on the first issue. */
	strict?: boolean;
}

const KNOWN_COLUMN_TYPES: ReadonlySet<string> = new Set([
	"string",
	"number",
	"date",
	"boolean",
	"enum",
	"multiEnum",
]);

/** Explicit meta boundary: rejects non-objects and unknown types instead of spreading garbage. */
function isColumnMeta(meta: unknown): meta is DataExplorerColumnMeta {
	if (typeof meta !== "object" || meta === null) return false;
	const candidate = meta as Record<string, unknown>;
	return (
		typeof candidate.displayName === "string" &&
		typeof candidate.type === "string" &&
		KNOWN_COLUMN_TYPES.has(candidate.type)
	);
}

function toColumnConfig(
	id: string,
	meta: DataExplorerColumnMeta,
): ColumnConfig {
	const config: ColumnConfig = {
		displayName: meta.displayName,
		id,
		type: meta.type,
	};
	if (meta.endOf !== undefined) config.endOf = meta.endOf;
	if (meta.icon !== undefined) config.icon = meta.icon;
	if (meta.max !== undefined) config.max = meta.max;
	if (meta.min !== undefined) config.min = meta.min;
	if (meta.operators !== undefined) config.operators = [...meta.operators];
	if (meta.options !== undefined) {
		config.options = meta.options.map((o) => ({
			label: o.label,
			value: o.value,
		}));
	}
	if (meta.quickOperator !== undefined)
		config.quickOperator = meta.quickOperator;
	if (meta.searchable !== undefined) config.searchable = meta.searchable;
	if (meta.startOf !== undefined) config.startOf = meta.startOf;
	return config;
}

/**
 * Strict variant of {@link extractColumnConfigs}: returns both the usable
 * configs and the per-definition issues that were skipped.
 */
export function extractColumnConfigsDetailed(
	defs: ReadonlyArray<{ id?: string; meta?: unknown }>,
	options?: ExtractColumnConfigOptions,
): { configs: ColumnConfig[]; issues: ColumnIssue[] } {
	const configs: ColumnConfig[] = [];
	const issues: ColumnIssue[] = [];
	defs.forEach((def, index) => {
		if (def.id == null) {
			issues.push({
				code: "INVALID_COLUMN_DEF",
				index,
				message: `[data-explorer] column at index ${index} missing id; skipped`,
			});
			return;
		}
		const meta: unknown = def.meta;
		if (!isColumnMeta(meta)) {
			issues.push({
				code: "INVALID_COLUMN_DEF",
				id: def.id,
				index,
				message: `[data-explorer] column "${def.id}" missing displayName/type; skipped`,
			});
			return;
		}
		configs.push(toColumnConfig(def.id, meta));
	});
	const first = issues[0];
	if (options?.strict && first !== undefined) {
		const details: Record<string, unknown> = { index: first.index };
		if (first.id !== undefined) details.id = first.id;
		throw new DataExplorerError("INVALID_COLUMN_DEF", first.message, details);
	}
	for (const issue of issues) options?.onInvalidColumn?.(issue);
	return { configs, issues };
}

/**
 * Derive headless column configs from TanStack column defs.
 * Invalid definitions are skipped; observe them via `options.onInvalidColumn`
 * or fail fast with `options.strict` (throws in dev *and* prod — prefer
 * `strict: process.env.NODE_ENV !== "production"` at the call site).
 */
export function extractColumnConfigs(
	defs: ReadonlyArray<{ id?: string; meta?: unknown }>,
	options?: ExtractColumnConfigOptions,
): ColumnConfig[] {
	return extractColumnConfigsDetailed(defs, options).configs;
}

/**
 * Matchable error taxonomy for `@adistack/data-explorer`.
 *
 * Every throw in the headless core uses {@link DataExplorerError} (or a
 * subclass) with a stable {@link DataExplorerErrorCode} so consumers can
 * branch on `error.code` instead of regex-matching `error.message`.
 * Plain `Error` and `console.*` are never used from library code.
 *
 * @example
 * ```ts
 * import { DataExplorerError, buildFilterWhere } from "@adistack/data-explorer";
 *
 * try {
 *   buildFilterWhere(filters, columns, mapping);
 * } catch (error) {
 *   if (error instanceof DataExplorerError && error.code === "UNKNOWN_COLUMN") {
 *     highlightChip(error.details?.["columnId"] as string);
 *   }
 * }
 * ```
 */

/** Stable codes for every failure the headless core can raise. */
export type DataExplorerErrorCode =
	| "MISSING_QUERY_CLIENT"
	| "INVALID_QUERY_OPTIONS"
	| "UNKNOWN_COLUMN"
	| "MISSING_MAPPING"
	| "INVALID_OPERATOR"
	| "INVALID_FILTER_VALUE"
	| "INVALID_FILTER_JSON"
	| "EMPTY_GROUP"
	| "NO_SEARCHABLE_COLUMN"
	| "UNSUPPORTED_DIALECT"
	| "INVALID_COLUMN_DEF"
	| "UNKNOWN_VIEW"
	| "VIEWS_NOT_CONFIGURED"
	| "MISSING_PROVIDER";

/** Base error for the data-explorer core. Branch on {@link code}. */
export class DataExplorerError extends Error {
	/** Stable machine-readable failure code. */
	readonly code: DataExplorerErrorCode;
	/** Structured context (e.g. `{ columnId }`) for UI highlighting. */
	readonly details?: Record<string, unknown>;

	constructor(
		code: DataExplorerErrorCode,
		message: string,
		details?: Record<string, unknown>,
	) {
		super(message);
		this.name = "DataExplorerError";
		this.code = code;
		if (details !== undefined) this.details = details;
	}
}

/**
 * Thrown when a context hook runs outside `<Provider>`.
 * Includes the hook name so copy-pasted `useSelectionContext` failures
 * point at the right call site.
 */
export class MissingProviderError extends DataExplorerError {
	constructor(hookName = "useDataExplorerContext") {
		super(
			"MISSING_PROVIDER",
			`${hookName} must be used within <Provider> (did you forget DataExplorerProvider / QueryClientProvider?).`,
			{ hookName },
		);
		this.name = "MissingProviderError";
	}
}

import { nanoid } from "nanoid";

import type { ColumnDataType } from "./columns.ts";

/**
 * All filter operators (canonical names only).
 *
 * Historical stored filters may still carry the `include` / `exclude`
 * short names (`include` ≡ `includeAll`, `exclude` ≡ `excludeAll`).
 * Those aliases are accepted at the serialization boundary
 * (`deserializeFilters` normalizes them via `normalizeOperator`) but are
 * not part of this union — new code must use `includeAll` / `excludeAll`.
 */
export type FilterOperator =
	| "eq"
	| "neq"
	| "contains"
	| "notContains"
	| "startsWith"
	| "endsWith"
	| "isEmpty"
	| "isNotEmpty"
	| "gt"
	| "gte"
	| "lt"
	| "lte"
	| "between"
	| "notBetween"
	| "in"
	| "notIn"
	| "includeAny"
	| "includeAll"
	| "excludeAny"
	| "excludeAll";

/** A single committed filter predicate. Stored shape; see {@link createFilter} for a typed constructor. */
export interface FilterCondition {
	columnId: string;
	combinator: "and" | "or";
	id: string;
	operator: FilterOperator;
	value: unknown;
}

export interface FilterGroup {
	combinator: "and" | "or";
	conditions: (FilterCondition | FilterGroup)[];
	id: string;
}

export function isFilterGroup(item: unknown): item is FilterGroup {
	return (
		typeof item === "object" &&
		item !== null &&
		"conditions" in item &&
		Array.isArray((item as FilterGroup).conditions)
	);
}

export interface SerializedFilterCondition {
	b: "and" | "or";
	c: string;
	i: string;
	o: FilterOperator;
	v: unknown;
}

/** True when at least one filter condition is present. */
export function hasFilters(conditions: readonly FilterCondition[]): boolean {
	return conditions.length > 0;
}

/**
 * Value shape per column type for editor autocomplete. The stored shape
 * stays {@link FilterCondition} (`value: unknown`); this only types the
 * constructor argument of {@link createFilter}.
 */
export type TypedFilterValue<T extends ColumnDataType> = T extends "number"
	? number | [number, number] | null
	: T extends "boolean"
		? boolean | null
		: T extends "date"
			? string | [string, string] | null
			: unknown;

/**
 * Typed `FilterCondition` constructor — autocomplete for the value shape
 * without changing the stored (serializable) representation.
 *
 * @example
 * ```ts
 * createFilter<"number">("estimate", "between", [1, 5]);
 * createFilter("title", "contains", "polish"); // untyped columns stay `unknown`
 * ```
 */
export function createFilter<T extends ColumnDataType = "string">(
	columnId: string,
	operator: FilterOperator,
	value: TypedFilterValue<T>,
): FilterCondition {
	return { columnId, combinator: "and", id: nanoid(), operator, value };
}

